import {
    Table,
    StringColumn,
    BooleanColumn,
    ListColumn,
    DateColumn,
    DateTimeColumn,
    ReferenceColumn,
    IntegerColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const change_request = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        email_client: true,
        hasWorkflow: true,
        live_feed: true,
    },
    audit: true,
    autoNumber: {
        number: 30000,
        prefix: 'CHG',
    },
    extends: 'task',
    extensible: true,
    label: 'Change Request',
    licensingConfig: {
        licenseModel: 'fulfiller',
        licenseCondition: 'opened_byISNOTEMPTY^EQ',
    },
    liveFeed: true,
    name: 'change_request',
    schema: {
        phase: StringColumn({
            default: 'requested',
            dropdown: 'dropdown_with_none',
            dependent: 'category',
            label: [
                {
                    hint: 'Dependent on Category value',
                    label: 'Phase',
                    plural: 'Phases',
                    language: 'en',
                },
            ],
        }),
        cab_required: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'CAB approval is needed for this change request',
                    label: 'CAB required',
                    plural: 'CAB required',
                    language: 'en',
                },
            ],
        }),
        justification: StringColumn({
            label: [
                {
                    hint: 'Enter benefits of implementing this change and impact if this change is not implemented',
                    label: 'Justification',
                    plural: 'Justifications',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
        }),
        on_hold_task: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Change Tasks that have been placed on hold by the change',
                    label: 'On Hold Change Tasks',
                    plural: 'On Hold Change Tasks',
                    language: 'en',
                },
            ],
            referenceTable: 'change_task',
        }),
        phase_state: StringColumn({
            default: 'open',
            dropdown: 'dropdown_with_none',
            dependent: 'phase',
            label: [
                {
                    hint: 'Dependent on Phase value',
                    label: 'Phase state',
                    plural: 'Phase states',
                    language: 'en',
                },
            ],
        }),
        cab_date: DateColumn({
            active: false,
            label: [
                {
                    hint: 'Enter the date of the CAB meeting',
                    label: 'CAB date',
                    plural: 'CAB dates',
                    language: 'en',
                },
            ],
        }),
        test_plan: StringColumn({
            label: [
                {
                    hint: 'Enter details of planned and completed tests prior to implementation that indicate the potential success of this change. Enter details of planned post-implementation tests to confirm success of this change',
                    label: 'Test plan',
                    plural: 'Test plans',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
        }),
        on_hold: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Indicates the Change Request is on hold',
                    label: 'On hold',
                    plural: 'On holds',
                    language: 'en',
                },
            ],
        }),
        production_system: BooleanColumn({
            label: 'Production system',
        }),
        end_date: DateTimeColumn({
            label: 'Planned end date',
        }),
        review_comments: StringColumn({
            label: 'Review comments',
            maxLength: 4000,
            spellCheck: true,
        }),
        type: StringColumn({
            default: 'javascript:ChangeModel.getDefaultTypeValue();',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    label: 'Type',
                    plural: 'Type',
                    language: 'en',
                },
            ],
        }),
        requested_by_date: DateTimeColumn({
            label: 'Requested by date',
        }),
        review_date: DateColumn({
            label: 'Review date',
        }),
        risk_impact_analysis: StringColumn({
            label: [
                {
                    hint: 'Enter potential risks and impact associated with this change. Include impact details if this change implementation is unsuccessful',
                    label: 'Risk and impact analysis',
                    plural: 'Risk and impact analysis',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
        }),
        std_change_producer_version: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Standard Change Template version',
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'std_change_producer_version',
        }),
        conflict_last_run: DateTimeColumn({
            label: 'Conflict last run',
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        category: StringColumn({
            default: 'Other',
            dropdown: 'dropdown_with_none',
            label: 'Category',
        }),
        cab_date_time: DateTimeColumn({
            label: [
                {
                    hint: 'Enter the date and time of the CAB meeting',
                    label: 'CAB date/time',
                    plural: 'CAB date/times',
                    language: 'en',
                },
            ],
        }),
        backout_plan: StringColumn({
            label: [
                {
                    hint: 'Enter steps to revert the change to its state prior to implementation. Include information regarding when the change can be backed out during implementation and if the change window includes time to backout',
                    label: 'Backout plan',
                    plural: 'Backout plans',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
        }),
        on_hold_reason: StringColumn({
            label: [
                {
                    hint: 'Provide the reason for putting the Change Request on hold',
                    label: 'On hold reason',
                    plural: 'On hold reasons',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
        }),
        risk: IntegerColumn({
            attributes: {
                field_decorations: 'change_risk_details',
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    label: 'Risk',
                    plural: 'Risk',
                    language: 'en',
                },
            ],
        }),
        cab_recommendation: StringColumn({
            label: [
                {
                    hint: 'Enter recommendation notes from the CAB',
                    label: 'CAB recommendation',
                    plural: 'CAB recommendations',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        change_plan: StringColumn({
            label: 'Change plan',
            maxLength: 4000,
            spellCheck: true,
        }),
        unauthorized: BooleanColumn({
            label: [
                {
                    hint: 'Change activity detected without prior authorization. To unset this field create an Outage of type Outage or Degradation.',
                    label: 'Unauthorized',
                    plural: 'Unauthorized',
                    language: 'en',
                },
            ],
        }),
        reason: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Reason',
        }),
        start_date: DateTimeColumn({
            label: 'Planned start date',
        }),
        review_status: IntegerColumn({
            dropdown: 'dropdown_with_none',
            label: 'Review status',
        }),
        copied_from: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Copied from',
            referenceTable: 'change_request',
        }),
        scope: IntegerColumn({
            default: '3',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    label: 'Scope',
                    plural: 'Scope',
                    language: 'en',
                },
            ],
        }),
        cab_delegate: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Identify a delegate to attend CAB in place of the assignee',
                    label: 'CAB delegate',
                    plural: 'CAB delegates',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
            referenceQual: 'roles=itil^ORroles=sn_change_read',
        }),
        implementation_plan: StringColumn({
            label: [
                {
                    hint: 'Enter sequential steps to implement this change. In addition, enter dependencies between steps and assignee details for each step',
                    label: 'Implementation plan',
                    plural: 'Implementation plans',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
        }),
        close_code: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Close code',
        }),
        outside_maintenance_schedule: BooleanColumn({
            label: 'Outside maintenance schedule',
        }),
        chg_model: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: 'javascript:ChangeModel.getDefaultModelValue(current);',
            label: 'Model',
            referenceTable: 'chg_model',
            referenceQual: 'javascript: ChangeModel.getRefQualForChangeRequest(current);',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        requested_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: 'javascript:gs.getUserID()',
            label: 'Requested by',
            referenceTable: 'sys_user',
        }),
        conflict_status: StringColumn({
            default: 'Not Run',
            choices: {
                Conflict: {
                    label: 'Conflict',
                    sequence: 0,
                },
                'No Conflict': {
                    label: 'No Conflict',
                    sequence: 1,
                },
                'Not Run': {
                    label: 'Not Run',
                    sequence: -1,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Conflict status',
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
    },
    textIndex: true,
})
